// Build the checked-in, completely offline SQLite worker from pinned wa-sqlite.
// npm install --prefix /a/temp/directory --ignore-scripts wa-sqlite@1.0.0 esbuild@0.25.12
// node .github/scripts/build_lrclib_local_runtime.mjs /a/temp/directory/node_modules
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../../', import.meta.url));
const dependencies = resolve(process.argv[2] || 'node_modules');
const require = createRequire(resolve(dependencies, '../package.json'));
const { build } = require(resolve(dependencies, 'esbuild'));
const packageRoot = dirname(require.resolve('wa-sqlite/package.json'));
const metadata = JSON.parse(readFileSync(resolve(packageRoot, 'package.json'), 'utf8'));
if (metadata.version !== '1.0.0') throw new Error('Expected wa-sqlite 1.0.0');
const wasm = readFileSync(resolve(packageRoot, 'dist/wa-sqlite.wasm'));
const wasmHash = createHash('sha256').update(wasm).digest('hex');
if (wasmHash !== '5384bc7d80d7981c2516f3ad6b02d886629985d178e5037e765d655f440bbf9f') throw new Error('Unexpected SQLite WASM bytes');
const built = await build({
  entryPoints: [resolve(root, 'local-db/LrclibLocalDatabaseWorker.mjs')], bundle: true, write: false,
  minify: true, format: 'iife', platform: 'browser', target: 'chrome110', nodePaths: [dependencies],
  define: { 'import.meta.url': '"file:///ivlyrics-local-database-worker.js"' },
  plugins: [{ name: 'inline-wasm', setup(build) {
    build.onResolve({ filter: /^ivlyrics-sqlite-wasm$/ }, () => ({ path: 'wasm', namespace: 'inline' }));
    build.onLoad({ filter: /.*/, namespace: 'inline' }, () => ({ contents: `export default ${JSON.stringify(wasm.toString('base64'))};`, loader: 'js' }));
  } }],
});
const license = readFileSync(resolve(packageRoot, 'LICENSE'), 'utf8');
const header = `/* Generated by .github/scripts/build_lrclib_local_runtime.mjs.\nwa-sqlite 1.0.0; WASM SHA-256 ${wasmHash}\n${license}\n*/\n`;
const source = built.outputFiles[0].text;
writeFileSync(resolve(root, 'LrclibLocalDatabaseRuntime.js'), header + `window.IvLyricsLocalLrclibWorkerSource = ${JSON.stringify(source)};\n`);
console.log(JSON.stringify({ file: 'LrclibLocalDatabaseRuntime.js', bytes: Buffer.byteLength(source), wasmHash }));
